rss.channel:
    {{ title }} | {{ section.title }} | {{ topic.title }}
    {{ topic_url }}

    {{ section.title }} / {{ topic.title }}
    {{ lang }}
{%- if posts %}
    {{ posts[0].created|rfc822 }}
{%- endif %}
{%- for post in posts %}


      {{ post.user.name }}: {{ topic.title }}
      {{ topic_url }}#{{ post.hexdigest }}
      {{ post.hexdigest }}
      {{ post.created|rfc822 }}
      {{ post.user.name }}
      {{ post.body|md2rst|rst2html|forceescape }}

{%- endfor %}
